// MessageSent is the resolver for the messageSent field.
func (r *subscriptionResolver) MessageSent(ctx context.Context, chatID string) (<-chan *model.Message, error) {
	log.Println("Subscription started for chatID:", chatID)

	msgChan := make(chan *model.Message, 1)
	genChan := make(chan interface{}, 1)

	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case data, ok := <-genChan:
				if !ok {
					return
				}
				if m, ok := data.(*model.Message); ok {
					msgChan <- m
				}
			}
		}
	}()

	// Register subscriber
	err := r.PubSub.Subscribe("chat:"+chatID, genChan)
	if err != nil {
		return nil, err
	}

	return msgChan, nil
}

